@router.get('/api/attachments/{file_id}')
async def get_attachment_stream(
    file_id: str,
    motor_db: AsyncIOMotorDatabase = Depends(get_motor_database),
    current_user: dict = Depends(get_jwt_payload)
):
    file_meta = await motor_db.attachment_metadata.find_one({"gridfs_id": ObjectId(file_id)})
    if not file_meta or current_user["sub"] not in file_meta["authorized_user_ids"]:
        raise HTTPException(status_code=403, detail="Access denied to attachment")

    fs_bucket = AsyncIOMotorGridFSBucket(motor_db)
    try:
        grid_in = await fs_bucket.open_download_stream(ObjectId(file_id))
    except Exception:
        raise HTTPException(status_code=404, detail="Attachment not found")

    async def file_generator():
        while chunk := await grid_in.readchunk():
            yield chunk

    return StreamingResponse(file_generator(), media_type=grid_in.metadata.get("content_type", "application/octet-stream"))
